import{_ as i,a as d,e as s,l as a,aT as l,A as o,t as n}from"./chunks/framework.CGV3_rZB.js";const E=JSON.parse('{"title":"KeepAlive","description":"在多个组件间动态切换时缓存被移除的组件实例","frontmatter":{"title":"KeepAlive","description":"在多个组件间动态切换时缓存被移除的组件实例","category":"vue","tags":["vue"]},"headers":[],"relativePath":"frontend/vue/keep-alive.md","filePath":"frontend/vue/keep-alive.md","lastUpdated":1749827948000}'),r={name:"frontend/vue/keep-alive.md"},c={id:"frontmatter-title",tabindex:"-1"};function h(t,e,p,k,u,b){return s(),d("div",null,[a("h1",c,[o(n(t.$frontmatter.title)+" ",1),e[0]||(e[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=l('<p><code>keep-alive</code> 是 Vue 的内置组件，用于<strong>缓存动态组件或路由组件</strong>，防止组件反复创建和销毁，提升性能，常用于页面切换、表单数据缓存场景。</p><h2 id="常用属性" tabindex="-1">常用属性 <a class="header-anchor" href="#常用属性" aria-label="Permalink to &quot;常用属性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>include</code></td><td>string / RegExp / Array</td><td>匹配名称的组件会被缓存</td></tr><tr><td><code>exclude</code></td><td>string / RegExp / Array</td><td>匹配名称的组件不会被缓存</td></tr><tr><td><code>max</code></td><td>number</td><td>最多缓存实例数，超出时采用 LRU 淘汰</td></tr></tbody></table><blockquote><p>⚠️ <code>include</code>/<code>exclude</code> 是根据组件的 <code>name</code> 属性匹配的，未命名的组件将无法命中。</p></blockquote><h2 id="生命周期钩子-组件中" tabindex="-1">生命周期钩子（组件中） <a class="header-anchor" href="#生命周期钩子-组件中" aria-label="Permalink to &quot;生命周期钩子（组件中）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>钩子</th><th>触发时机</th></tr></thead><tbody><tr><td><code>activated</code></td><td>被 <code>keep-alive</code> 激活时触发</td></tr><tr><td><code>deactivated</code></td><td>被 <code>keep-alive</code> 暂时移除时触发</td></tr><tr><td><code>created</code></td><td>只在首次加载时触发一次</td></tr><tr><td><code>destroyed</code></td><td>缓存组件不会触发该钩子</td></tr></tbody></table><h2 id="原理简述" tabindex="-1">原理简述 <a class="header-anchor" href="#原理简述" aria-label="Permalink to &quot;原理简述&quot;">​</a></h2><ul><li><code>keep-alive</code> 内部维护一个缓存对象 <code>cache</code>，键为组件名称或唯一 key，值为对应的 vnode 实例；</li><li>首次渲染时，组件会被创建并加入缓存；</li><li>再次渲染时，若命中缓存，则直接复用 vnode 实例；</li><li>超出 <code>max</code> 限制时，淘汰最久未使用组件（LRU 算法）；</li><li>被缓存组件不会重新执行 <code>created</code>，但会执行 <code>activated</code>。</li></ul><h2 id="常见使用场景" tabindex="-1">常见使用场景 <a class="header-anchor" href="#常见使用场景" aria-label="Permalink to &quot;常见使用场景&quot;">​</a></h2><ol><li><strong>路由缓存</strong>（防止重复请求和状态丢失）：</li></ol><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">keep-alive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;router-view /&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">keep-alive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ol start="2"><li><strong>表单填写保留状态</strong>：</li></ol><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">keep-alive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;FormPage&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;component :is=&quot;currentPage&quot; /&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">keep-alive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ol start="3"><li><strong>复杂视图切换（如 tab 页）避免销毁和重建</strong></li></ol><h2 id="vue2-vs-vue3-简述" tabindex="-1">Vue2 vs Vue3（简述） <a class="header-anchor" href="#vue2-vs-vue3-简述" aria-label="Permalink to &quot;Vue2 vs Vue3（简述）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>Vue 2</th><th>Vue 3</th></tr></thead><tbody><tr><td>缓存方式</td><td>手动匹配 <code>name</code></td><td>支持基于 <code>setup</code> name 推导</td></tr><tr><td>底层实现</td><td>使用 vnode.key + LRU Map 实现</td><td>更细粒度缓存、内置 Suspense 支持</td></tr><tr><td>类型支持</td><td>Options API</td><td>支持 Composition API</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>匹配组件名时要确保组件设置了 <code>name</code>；</li><li><code>keep-alive</code> 只缓存组件实例，不缓存 DOM 快照；</li><li>对缓存组件数据的更新，应放在 <code>activated</code> 钩子中处理；</li><li>可通过 <code>key</code> 改变强制刷新组件缓存。</li></ul><h2 id="典型面试问题及答案" tabindex="-1">典型面试问题及答案 <a class="header-anchor" href="#典型面试问题及答案" aria-label="Permalink to &quot;典型面试问题及答案&quot;">​</a></h2><h3 id="_1-keep-alive-的作用是什么-使用场景有哪些" tabindex="-1">1. <code>keep-alive</code> 的作用是什么？使用场景有哪些？ <a class="header-anchor" href="#_1-keep-alive-的作用是什么-使用场景有哪些" aria-label="Permalink to &quot;1. `keep-alive` 的作用是什么？使用场景有哪些？&quot;">​</a></h3><p>用于缓存组件实例，避免反复销毁重建，提升性能。常用于路由切换、tab 页面、表单缓存等场景。</p><h3 id="_2-include-和-exclude-如何工作" tabindex="-1">2. <code>include</code> 和 <code>exclude</code> 如何工作？ <a class="header-anchor" href="#_2-include-和-exclude-如何工作" aria-label="Permalink to &quot;2. `include` 和 `exclude` 如何工作？&quot;">​</a></h3><p>根据组件的 <code>name</code> 属性进行匹配，可用字符串、正则或数组。匹配上的会被缓存，排除的不会缓存。</p><h3 id="_3-生命周期钩子-activated-和-deactivated-的使用场景" tabindex="-1">3. 生命周期钩子 <code>activated</code> 和 <code>deactivated</code> 的使用场景？ <a class="header-anchor" href="#_3-生命周期钩子-activated-和-deactivated-的使用场景" aria-label="Permalink to &quot;3. 生命周期钩子 `activated` 和 `deactivated` 的使用场景？&quot;">​</a></h3><ul><li><code>activated</code>: 每次组件从缓存中激活时触发，可用于刷新数据。</li><li><code>deactivated</code>: 组件被缓存挂起时触发，可用于暂停计时器、取消订阅等。</li></ul><h3 id="_4-为什么缓存组件的数据可能不是最新的-如何刷新" tabindex="-1">4. 为什么缓存组件的数据可能不是最新的？如何刷新？ <a class="header-anchor" href="#_4-为什么缓存组件的数据可能不是最新的-如何刷新" aria-label="Permalink to &quot;4. 为什么缓存组件的数据可能不是最新的？如何刷新？&quot;">​</a></h3><p>因为组件实例没有被销毁，数据仍为上次的状态。可在 <code>activated</code> 钩子中重新加载数据。</p><h3 id="_5-如何只缓存某些组件-如何清除某个缓存组件" tabindex="-1">5. 如何只缓存某些组件？如何清除某个缓存组件？ <a class="header-anchor" href="#_5-如何只缓存某些组件-如何清除某个缓存组件" aria-label="Permalink to &quot;5. 如何只缓存某些组件？如何清除某个缓存组件？&quot;">​</a></h3><ul><li>使用 <code>include</code> 或 <code>exclude</code> 控制。</li><li>手动更改组件 <code>key</code> 或使用动态 <code>is</code> 切换组件强制重建。</li></ul><h3 id="_6-keep-alive-的缓存原理-是否会缓存-dom" tabindex="-1">6. <code>keep-alive</code> 的缓存原理？是否会缓存 DOM？ <a class="header-anchor" href="#_6-keep-alive-的缓存原理-是否会缓存-dom" aria-label="Permalink to &quot;6. `keep-alive` 的缓存原理？是否会缓存 DOM？&quot;">​</a></h3><p>缓存的是组件实例（VNode 和组件状态），不会缓存 DOM 结构，但会保留虚拟 DOM 及状态以便复用。</p><h3 id="_7-如何取消缓存组件" tabindex="-1">7. 如何取消缓存组件？ <a class="header-anchor" href="#_7-如何取消缓存组件" aria-label="Permalink to &quot;7. 如何取消缓存组件？&quot;">​</a></h3><ul><li>使用 <code>exclude</code> 属性将组件排除出缓存；</li><li>动态改变 <code>key</code> 强制组件重新渲染（如 <code>&lt;component :is=&quot;view&quot; :key=&quot;dynamicKey&quot; /&gt;</code>）；</li><li>条件渲染时去掉 <code>keep-alive</code> 包裹；</li><li>在 Vue3 中还可以使用 <code>cache</code> 对象引用手动调用 <code>cache.delete(key)</code>（需要结合自定义渲染器或高级特性）。</li></ul>',33))])}const m=i(r,[["render",h]]);export{E as __pageData,m as default};
